def transform(grid):
 h=len(grid); w=len(grid[0]); seen=set(); comps=[]
 for r in range(h):
  for c in range(w):
   col=grid[r][c]
   if col==0 or (r,c) in seen: continue
   st=[(r,c)]; seen.add((r,c)); pts=[]
   while st:
    y,x=st.pop(); pts.append((y,x))
    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
     q=(y+dy,x+dx)
     if 0<=q[0]<h and 0<=q[1]<w and q not in seen and grid[q[0]][q[1]]==col: seen.add(q); st.append(q)
   comps.append((col,pts))
 # preserve x, let components settle bottom, process lower components first
 out=[[0]*w for _ in range(h)]
 comps.sort(key=lambda z:max(y for y,x in z[1]),reverse=True)
 for col,pts in comps:
  d=0
  while all(y+d+1<h and out[y+d+1][x]==0 for y,x in pts): d+=1
  for y,x in pts: out[y+d][x]=col
 return out
